package thaumcraft.research;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BookCompletionTest {
 JsonObject resource(String file)throws Exception{return JsonParser.parseString(Files.readString(Path.of("src/modern/resources/assets/thaumcraft/"+file))).getAsJsonObject();}
 @Test void spanishHasEveryReferencedTitleStageAndAddendum()throws Exception{var es=resource("lang/es_es.json");var keys=new HashSet<String>();for(var e:ResearchCatalog.ENTRIES){keys.add(e.name());for(var s:e.stages())keys.add(s.text());for(var a:e.addenda())keys.add(a.text());}assertEquals(433,keys.size());for(var key:keys){assertTrue(es.has(key),key);assertFalse(es.get(key).getAsString().isBlank(),key);}}
 @Test void noOriginalRecipeReferenceIsLeftWithoutADiagram()throws Exception{var v=resource("knowledge/recipe_views.json");for(var e:ResearchCatalog.ENTRIES){for(var s:e.stages())for(var key:s.recipes())assertTrue(v.has(key),key);for(var a:e.addenda())for(var key:a.recipes())assertTrue(v.has(key),key);}assertEquals(16,v.getAsJsonObject("thaumcraft:Banners").getAsJsonArray("choices").size());var basic=v.getAsJsonObject("thaumcraft:baubles_stuff").getAsJsonArray("choices");assertEquals(6,basic.size());for(var ref:basic)assertFalse(ref.getAsString().contains("infusion/"),"Basic group reveals advanced accessories");for(var metal:List.of("tin","silver","lead")){var page=v.getAsJsonObject("thaumcraft:metal_purification_"+metal);assertEquals("c:ores/"+metal,page.get("optional_tag").getAsString());}}
 @Test void structurePagesRetainTheActualAssemblyMaterials()throws Exception{var v=resource("knowledge/recipe_views.json");for(var key:List.of("infusionaltar","infusionaltarancient","infusionaltareldritch")){var page=v.getAsJsonObject("thaumcraft:"+key);var layers=page.getAsJsonArray("layers");assertEquals(3,layers.size());int stones=0;for(var layer:layers)for(var row:layer.getAsJsonArray())stones+=(int)row.getAsString().chars().filter(c->c=='S').count();assertEquals(8,stones);}var oven=v.getAsJsonObject("thaumcraft:infernalfurnace");int bricks=0,obsidian=0;for(var layer:oven.getAsJsonArray("layers"))for(var row:layer.getAsJsonArray()){bricks+=row.getAsString().chars().filter(c->c=='N').count();obsidian+=row.getAsString().chars().filter(c->c=='O').count();}assertEquals(12,bricks);assertEquals(12,obsidian);}
 @Test void originalMarkupKeepsPageBoundariesImagesAndDividers(){var parts=BookMarkup.parse("before<BR>paragraph<LINE>next<DIV><PAGE><IMG>thaumcraft:textures/research/research5.png:128:0:128:136:1</IMG>after");assertTrue(parts.stream().anyMatch(p->p.kind()==BookMarkup.Kind.PAGE));assertTrue(parts.stream().anyMatch(p->p.kind()==BookMarkup.Kind.DIVIDER));assertEquals(1,parts.stream().filter(p->p.kind()==BookMarkup.Kind.IMAGE).count());assertEquals("after",parts.getLast().text());assertEquals(136,parts.stream().filter(p->p.image()!=null).findFirst().orElseThrow().image().height());}
 @Test void malformedImageNeverLeaksResourceSyntaxIntoText(){var parts=BookMarkup.parse("A<IMG>https://wrong</IMG>B<IMG>thaumcraft:textures/a.png:0:0:128:128:NaN</IMG>C");assertEquals("ABC",parts.stream().map(BookMarkup.Part::text).reduce("",String::concat));assertTrue(parts.stream().noneMatch(p->p.image()!=null));}
 @Test void originalTextStylesAndAccentInsensitiveSearchArePreserved(){var c=BookMarkup.formatted("plain §lbold§r plain");assertEquals("plain bold plain",c.getString());assertTrue(c.getSiblings().get(1).getStyle().isBold());assertFalse(c.getSiblings().get(2).getStyle().isBold());assertEquals("infusion",BookMarkup.searchable("Infusión"));}
}
